#[tauri::command]
pub async fn owner_recognize_image_text(
    owner: String,
    png: String,
    app: tauri::State<'_, AppState>,
    node: tauri::State<'_, NodeState>,
) -> Result<String, CommandError> {
    let admission = RuntimeAdmission::capture(&app, &node, &owner)?;
    let bytes = decode_png(&png)?;
    static CAPACITY: std::sync::Arc<tokio::sync::Semaphore> = std::sync::Arc::new(tokio::sync::Semaphore::const_new(1));
    let permit = CAPACITY.clone().try_acquire_owned()
        .map_err(|_| CommandError::InvalidInput("image recognition is busy; try again".into()))?;
    let worker_admission = admission.clone();
    let text = tokio::task::spawn_blocking(move || {
        let _permit = permit;
        // Check authority after blocking-pool admission; no session guard spans OCR.
        worker_admission.lease();
        recognize(&bytes)
    }).await.map_err(|_| CommandError::InvalidInput("image recognition failed".into()))??;
    admission.with_runtime(|runtime| admission.checked(runtime, || Ok(text))).await
}

#[cfg(not(target_os = "macos"))]
fn recognize(_bytes: &[u8]) -> Result<String, CommandError> {
    Err(CommandError::InvalidInput("system image text is unavailable on this platform".into()))
}

#[cfg(target_os = "macos")]
fn recognize(bytes: &[u8]) -> Result<String, CommandError> {
    use objc2::{class, msg_send, rc::{autoreleasepool, Retained}, runtime::AnyObject};
    use objc2_foundation::NSString;
    #[link(name = "Vision", kind = "framework")]
    unsafe extern "C" {}
    // SAFETY: Foundation/Vision objects stay on this worker, NSData copies bounded input,
    // selectors match Apple's Objective-C APIs, and retained values outlive every call.
    unsafe { autoreleasepool(|_| {
        let data: Retained<AnyObject> = msg_send![class!(NSData), dataWithBytes: bytes.as_ptr(), length: bytes.len()];
        let request: Retained<AnyObject> = msg_send![class!(VNRecognizeTextRequest), new];
        let _: () = msg_send![&request, setRecognitionLevel: 0_isize];
        let zh = NSString::from_str("zh-Hans");
        let en = NSString::from_str("en-US");
        let languages = [Retained::as_ptr(&zh).cast::<AnyObject>(), Retained::as_ptr(&en).cast::<AnyObject>()];
        let languages: Retained<AnyObject> = msg_send![class!(NSArray), arrayWithObjects: languages.as_ptr(), count: languages.len()];
        let _: () = msg_send![&request, setRecognitionLanguages: &*languages];
        let options: Retained<AnyObject> = msg_send![class!(NSDictionary), new];
        let handler: Retained<AnyObject> = msg_send![class!(VNImageRequestHandler), alloc];
        let handler: Retained<AnyObject> = msg_send![handler, initWithData: &*data, options: &*options];
        let requests = [Retained::as_ptr(&request)];
        let requests: Retained<AnyObject> = msg_send![class!(NSArray), arrayWithObjects: requests.as_ptr(), count: 1_usize];
        let mut error: *mut AnyObject = std::ptr::null_mut();
        let ok: bool = msg_send![&handler, performRequests: &*requests, error: &mut error];
        if !ok { return Err(CommandError::InvalidInput("system image recognition failed".into())); }
        let results: Retained<AnyObject> = msg_send![&request, results];
        let count: usize = msg_send![&results, count];
        let mut lines = Vec::new();
        let mut total = 0;
        for index in 0..count.min(4096) {
            let observation: Retained<AnyObject> = msg_send![&results, objectAtIndex: index];
            let candidates: Retained<AnyObject> = msg_send![&observation, topCandidates: 1_usize];
            let n: usize = msg_send![&candidates, count];
            if n == 0 { continue; }
            let candidate: Retained<AnyObject> = msg_send![&candidates, objectAtIndex: 0_usize];
            let text: Retained<NSString> = msg_send![&candidate, string];
            let text = text.to_string();
            total += text.len();
            if total > 256 * 1024 { return Err(CommandError::InvalidInput("recognized text exceeds limit".into())); }
            lines.push(text);
        }
        Ok(lines.join("\n"))
    }) }
}
